class Node:
    def __init__(self, val, nxt=None):
        self.val, self.next = val, nxt
def reverse(head):
    prev = None
    while head:
        head.next = prev
        prev, head = head, head.next
    return prev

r = reverse(Node(1, Node(2, Node(3))))
print(r.val, r.next)

def balanced(s):
    pairs = {")": "(", "]": "["}
    stack = []
    for ch in s:
        if ch in "([":
            stack.append(ch)
        elif not stack or stack.pop() != pairs[ch]:
            return False
    return not stack

print(balanced("([)]"), balanced("(()"))

class N:
    def __init__(self, v, l=None, r=None):
        self.v, self.l, self.r = v, l, r

def ok(n):
    if n is None: return True
    if n.l and n.l.v > n.v: return False
    if n.r and n.r.v < n.v: return False
    return ok(n.l) and ok(n.r)

root = N(10, N(5, None, N(12)), N(15))
print(ok(root))

